world node {
    use aap:caps/types@0.1.0.{conversation-context, response-result};

    import aap:caps/kb-read@0.1.0;
    import aap:caps/tool-llm@0.1.0;

    export run: func(ctx: conversation-context) -> response-result;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        use crate::aap::caps::kb_read;
        use crate::aap::caps::tool_llm::{self, Reply};

        let system =
            "You are a customer support agent. Answer the user's question using the \
             supplied knowledge. If you need more information, request the `lookup` tool.";

        let mut prompt = String::new();
        prompt.push_str("Intent: ");
        prompt.push_str(intent_label(ctx.intent));
        prompt.push_str("\nQuestion: ");
        prompt.push_str(&ctx.question);
        prompt.push('\n');
        if !ctx.knowledge.is_empty() {
            prompt.push_str("Knowledge:\n");
            for k in &ctx.knowledge {
                prompt.push_str("- ");
                prompt.push_str(k);
                prompt.push('\n');
            }
        }

        // Bounded tool-orchestration loop. The only tool this node is
        // authorised to invoke is `lookup`, backed by the read-only
        // knowledge-base handle; any other requested tool is reported back
        // to the model as unavailable rather than acted on.
        let mut rounds: u32 = 0;
        loop {
            match tool_llm::generate(system, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    rounds += 1;
                    if rounds > 8 {
                        return ResponseResult::Error(LlmError {
                            message: "tool-orchestration loop exceeded its round limit"
                                .to_string(),
                        });
                    }
                    if req.tool == "lookup" {
                        let results = kb_read::lookup(&req.query);
                        prompt.push_str("\nTool lookup results for \"");
                        prompt.push_str(&req.query);
                        prompt.push_str("\":\n");
                        if results.is_empty() {
                            prompt.push_str("(no matches)\n");
                        } else {
                            for r in &results {
                                prompt.push_str("- ");
                                prompt.push_str(r);
                                prompt.push('\n');
                            }
                        }
                    } else {
                        prompt.push_str("\nTool \"");
                        prompt.push_str(&req.tool);
                        prompt.push_str("\" is not available to this node.\n");
                    }
                }
            }
        }
    }
}

export!(Node);
